#ifdef CONFIG_DLL
// ============================================================================
// AHKDeck error sink (see deck_sink.h)
// ----------------------------------------------------------------------------
// One UTF-8 JSON line per problem, built here on the failing script's thread.
// Nothing is allocated and no I/O happens: the host callback only enqueues.
// ============================================================================

#define DECK_JSON_MAX (16 * 1024)

static DeckErrorSinkFn s_DeckErrorSink = nullptr;
static volatile LONG s_DeckErrorSeq = 0;

bool g_DeckIsolatedScripts = false;

static void DeckPut(char *aBuf, int aCap, int &aLen, const char *aText)
{
	while (*aText && aLen < aCap - 1)
		aBuf[aLen++] = *aText++;
	aBuf[aLen] = '\0';
}

static void DeckPutEscaped(char *aBuf, int aCap, int &aLen, const char *aText)
{
	while (*aText && aLen < aCap - 8)
	{
		unsigned char c = (unsigned char)*aText++;
		if (c == '"' || c == '\\')
		{
			aBuf[aLen++] = '\\';
			aBuf[aLen++] = (char)c;
		}
		else if (c < 0x20)
		{
			static const char hex[] = "0123456789abcdef";
			aBuf[aLen++] = '\\';
			aBuf[aLen++] = 'u';
			aBuf[aLen++] = '0';
			aBuf[aLen++] = '0';
			aBuf[aLen++] = hex[c >> 4];
			aBuf[aLen++] = hex[c & 0xF];
		}
		else
			aBuf[aLen++] = (char)c;
	}
	aBuf[aLen] = '\0';
}

// TCHAR -> UTF-8, truncated to fit. Returns the byte length.
static int DeckUtf8(LPCTSTR aSrc, char *aDst, int aDstSize)
{
	if (aDstSize <= 0)
		return 0;
#ifdef UNICODE
	int n = WideCharToMultiByte(CP_UTF8, 0, aSrc, -1, aDst, aDstSize - 1, nullptr, nullptr);
	if (n <= 0)
		n = 0;
	aDst[n] = '\0';
	return n;
#else
	int n = (int)_tcslen(aSrc);
	if (n > aDstSize - 1)
		n = aDstSize - 1;
	memcpy(aDst, aSrc, n);
	aDst[n] = '\0';
	return n;
#endif
}

static void DeckTimestamp(char *aBuf, int aCap)
{
	SYSTEMTIME st;
	GetLocalTime(&st);
	snprintf(aBuf, aCap, "%04u-%02u-%02uT%02u:%02u:%02u.%03u",
		st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond, st.wMilliseconds);
}

bool DeckNotifyError(LPCTSTR aMessage, LPCTSTR aExtra, Line *aLine, int aErrorType, bool aWarn)
{
	if (!s_DeckErrorSink)
		return false;

	// Resolve file/line exactly the way ShowError() picks them, so the log
	// matches what the official dialog would have shown.
	int file_index = 0, line_number = 0;
	if (aLine)
	{
		file_index = (int)aLine->mFileIndex;
		line_number = (int)aLine->mLineNumber;
	}
	else if (g_script)
	{
		file_index = (int)g_script->mCurrFileIndex;
		line_number = (int)g_script->mCombinedLineNumber;
	}
	LPCTSTR file = _T("");
	if (file_index >= 0 && file_index < Line::sSourceFileCount && Line::sSourceFile[file_index])
		file = Line::sSourceFile[file_index];

	const char *severity = aWarn ? "warn"
		: aErrorType == CRITICAL_ERROR ? "critical"
		: aErrorType == FAIL_OR_OK ? "fail_or_ok" : "fail";
	const char *phase = (g_script && g_script->mIsReadyToExecute) ? "runtime" : "load";

	char message[4096], extra[4096], file_utf8[1024], ts[32];
	DeckUtf8(aMessage ? aMessage : _T(""), message, _countof(message));
	DeckUtf8(aExtra ? aExtra : _T(""), extra, _countof(extra));
	DeckUtf8(file, file_utf8, _countof(file_utf8));
	DeckTimestamp(ts, _countof(ts));

	int seq = (int)InterlockedIncrement(&s_DeckErrorSeq);
	unsigned thread = (unsigned)GetCurrentThreadId();

	char json[DECK_JSON_MAX];
	_snprintf_s(json, _countof(json), _TRUNCATE,
		"{\"ts\":\"%s\",\"thread\":%u,\"seq\":%d,\"kind\":\"%s\",\"phase\":\"%s\",\"severity\":\"%s\",\"file\":\"",
		ts, thread, seq, aWarn ? "warn" : "error", phase, severity);
	int n = (int)strlen(json);
	DeckPutEscaped(json, _countof(json), n, file_utf8);
	DeckPut(json, _countof(json), n, "\",\"line\":");
	_snprintf_s(json + n, _countof(json) - n, _TRUNCATE, "%d,\"message\":\"", line_number);
	n = (int)strlen(json);
	DeckPutEscaped(json, _countof(json), n, message);
	DeckPut(json, _countof(json), n, "\",\"extra\":\"");
	DeckPutEscaped(json, _countof(json), n, extra);
	DeckPut(json, _countof(json), n, "\"}");

	s_DeckErrorSink(json);
	return true;
}
#endif // CONFIG_DLL


